const rows: Row[] = [
  // United States — the period and cited text, not party membership, defines each reading.
  { id:'george-washington', name:'George Washington', category:'historical-figure', period:'Presidência e discursos inaugurais, 1789–1797', values:[67,78,64,50,62,67,50,50,54,50,51,50], rationale:'O discurso inaugural reconhece os limites constitucionais do executivo, a união federal, defesa comum e neutralidade externa.', caveats:'A república escravista restringia cidadania e sufrágio. Os centros em economia, costumes e tecnologia indicam ausência de evidência equivalente, não moderação.', title:'First Inaugural Address, 1789', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-16', note:'Transcrição do discurso inaugural de Washington, registro primário hospedado pelo American Presidency Project.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',int:'medium'} },
  { id:'thomas-jefferson', name:'Thomas Jefferson', category:'historical-figure', period:'Presidência e escritos políticos, 1801–1809', values:[79,72,42,50,43,70,50,50,58,58,65,50], rationale:'Discursos e escritos defendem governo limitado, autonomia republicana e cautela com alianças permanentes; outras dimensões não se inferem com a mesma segurança.', caveats:'Jefferson escravizou pessoas e suas declarações universalistas coexistem com exclusões raciais e políticas. O vetor não reconcilia essa contradição.', title:'First Inaugural Address, 1801', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-19', note:'Transcrição integral do próprio discurso de Jefferson sobre governo republicano e política externa.', evidence:{est:'medium',rep:'medium',dip:'medium',int:'medium',mor:'medium'} },
  { id:'alexander-hamilton', name:'Alexander Hamilton', category:'historical-figure', period:'Federalist Papers e programa fiscal, 1787–1795', values:[36,55,72,50,58,46,56,76,66,50,42,62], rationale:'Os Federalist Papers e os relatórios de finanças defendem um governo federal robusto, crédito público, manufatura e capacidade militar.', caveats:'A escala não traduz a oposição do período entre república e monarquia em categorias modernas; alguns textos foram escritos em colaboração.', title:'The Federalist Papers, 1787–1788', url:'https://avalon.law.yale.edu/subject_menus/fed.asp', note:'Arquivo da Yale Law School com ensaios políticos originais assinados por Hamilton, Madison e Jay; o recorte usa os ensaios de Hamilton identificados no índice.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',eco:'medium',con:'medium',com:'medium'} },
  { id:'james-madison', name:'James Madison', category:'historical-figure', period:'Constituição, Federalist Papers e presidência, 1787–1817', values:[69,74,54,50,54,56,50,50,50,50,57,50], rationale:'Seus textos constitucionais articulam federalismo, controles republicanos, direitos e governo representativo; não há base equivalente para a maioria dos eixos econômicos e culturais.', caveats:'O federalismo de Madison mudou ao longo da carreira; suas ações e propriedade escravista entram em conflito com a linguagem universal de direitos.', title:'The Federalist Papers, 1787–1788', url:'https://avalon.law.yale.edu/subject_menus/fed.asp', note:'Arquivo de ensaios primários de Madison, Hamilton e Jay; consultar itens assinados por Madison.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',mor:'medium'} },
  { id:'john-adams', name:'John Adams', category:'historical-figure', period:'Discursos e presidência, 1797–1801', values:[62,60,58,50,61,62,50,50,53,50,50,50], rationale:'O discurso de posse privilegia independência nacional, defesa comum e preservação constitucional; eixos sem programa explícito ficam desconhecidos.', caveats:'O Alien and Sedition Acts e a guerra naval tornam liberdade civil e segurança contextuais. Não é uma avaliação completa de sua carreira.', title:'Inaugural Address, 1797', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-21', note:'Transcrição do discurso de posse de Adams, uma fonte primária para seu programa presidencial inicial.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium'} },
  { id:'john-quincy-adams', name:'John Quincy Adams', category:'historical-figure', period:'Presidência e atuação antiescravista, 1825–1848', values:[64,79,51,50,49,58,56,63,50,50,80,50], rationale:'O discurso presidencial defende obras públicas e bem-estar geral; sua atuação posterior no Congresso contra a regra da mordaça documenta oposição à escravidão e defesa de petição.', caveats:'A entrada combina dois períodos explicitados. O centro em temas sem pronunciamento sustentado não representa posição observada.', title:'Inaugural Address, 1825, e registros parlamentares', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-25', note:'Texto primário de posse; o arquivo do Congresso registra a campanha parlamentar antiescravista posterior de Adams.', evidence:{est:'medium',rep:'medium',pod:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'andrew-jackson', name:'Andrew Jackson', category:'historical-figure', period:'Presidência e política federal, 1829–1837', values:[42,63,68,82,62,30,46,48,52,52,31,50], rationale:'Mensagens presidenciais defendem remoção indígena coercitiva, autoridade executiva forte e expansão do poder nacional em política territorial.', caveats:'O perfil registra medidas e argumentos documentados, inclusive a violência estatal; o eixo de assimilação não é endosso nem descrição de todos os grupos atingidos.', title:'Second Inaugural Address, 1833, e mensagem sobre remoção indígena', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-0', note:'Arquivo primário de mensagens e discursos presidenciais de Jackson; a nota do perfil se restringe às políticas do mandato.', evidence:{est:'medium',rep:'medium',pod:'medium',imi:'high',dip:'medium',int:'medium'} },
  { id:'james-monroe', name:'James Monroe', category:'historical-figure', period:'Presidência e política externa, 1817–1825', values:[62,67,57,50,48,52,50,50,54,50,52,50], rationale:'Discursos presidenciais sustentam republicanismo constitucional, defesa nacional e a política hemisférica associada à Doutrina Monroe.', caveats:'A Doutrina Monroe foi uma declaração de política externa, não uma prova de não intervenção em todos os conflitos. A codificação de outros eixos é limitada.', title:'First Inaugural Address, 1817', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-23', note:'Transcrição primária do discurso inaugural de Monroe; textos de política externa do mandato são acessíveis no mesmo arquivo.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium'} },
  { id:'james-k-polk', name:'James K. Polk', category:'historical-figure', period:'Presidência e expansão territorial, 1845–1849', values:[44,62,69,62,78,29,51,55,68,50,44,50], rationale:'A posse e as mensagens de governo justificam expansão continental e guerra com o México; o uso da força e a anexação são parte central do recorte.', caveats:'O vetor descreve o programa expansionista deste mandato; não generaliza políticas posteriores nem usa os resultados territoriais como prova de apoio popular.', title:'Inaugural Address, 1845', url:'https://www.presidency.ucsb.edu/documents/app-attributes/inaugural?items_per_page=60&page=1', note:'Índice arquivístico de discursos inaugurais inclui a transcrição primária de Polk, datada de 4 de março de 1845.', evidence:{est:'medium',rep:'medium',pod:'medium',imi:'medium',dip:'high',int:'medium'} },
  { id:'ulysses-s-grant', name:'Ulysses S. Grant', category:'historical-figure', period:'Presidências e Reconstrução, 1869–1877', values:[61,74,67,50,66,47,54,61,51,50,76,51], rationale:'Discursos e medidas federais de Reconstrução sustentaram cidadania e proteção do voto negro, com aplicação de força federal contra a violência política.', caveats:'A classificação cobre a presidência e não apaga limites, corrupção administrativa ou os conflitos de implementação da Reconstrução.', title:'First Inaugural Address, 1869', url:'https://www.presidency.ucsb.edu/documents/app-categories/spoken-addresses-and-remarks/presidential/inaugural-addresses?items_per_page=40&page=1', note:'Arquivo de discursos inaugurais de Grant e seus contemporâneos; o perfil delimita a presidência e a aplicação das emendas de Reconstrução.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',eco:'medium',mor:'high'} },
  { id:'theodore-roosevelt', name:'Theodore Roosevelt', category:'historical-figure', period:'Presidência e programa progressista, 1901–1909', values:[55,73,66,56,78,30,62,75,57,51,65,56], rationale:'O Square Deal, a regulação de trustes, conservação pública e expansão naval aparecem em suas mensagens e ações presidenciais.', caveats:'Sua linguagem progressista coexistiu com imperialismo e hierarquias raciais. O vetor não transforma a autodescrição partidária em dados de todos os eixos.', title:'Second Inaugural Address, 1905', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-10', note:'Transcrição da posse de Roosevelt em 1905; mensagens e discursos de seu governo estão indexados no arquivo presidencial.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'medium',con:'medium'} },
  { id:'woodrow-wilson', name:'Woodrow Wilson', category:'historical-figure', period:'Presidências, 1913–1921', values:[57,72,64,55,75,48,57,67,67,54,57,58], rationale:'A Nova Liberdade, a criação do Federal Reserve e a entrada dos EUA na Primeira Guerra documentam regulação econômica, segurança nacional e intervenção externa.', caveats:'Wilson resegregou agências federais e a retórica de autodeterminação conviveu com o colonialismo. O escopo inclui decisões controversas da presidência.', title:'Fourteen Points Address, 1918', url:'https://www.archives.gov/milestone-documents/president-woodrow-wilsons-14-points', note:'Discurso primário preservado pelos National Archives sobre a ordem pós-guerra e autodeterminação.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'william-howard-taft', name:'William Howard Taft', category:'historical-figure', period:'Presidência e política econômica, 1909–1913', values:[55,68,57,52,64,51,49,55,62,50,47,50], rationale:'Mensagens presidenciais defendem reformas tarifárias, confiança em tribunais e uma política externa de diplomacia do dólar.', caveats:'O texto inaugural é uma fonte programática limitada. Não inferimos posição cultural ou tecnológica sem declaração pertinente.', title:'Inaugural Address, 1909', url:'https://www.presidency.ucsb.edu/documents/presidential-documents-archive-guidebook/inaugural-addresses', note:'A coleção de transcrições primárias do arquivo lista e liga a posse de Taft, em 4 de março de 1909.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',com:'medium'} },
  { id:'herbert-hoover', name:'Herbert Hoover', category:'historical-figure', period:'Presidência e resposta inicial à Depressão, 1929–1933', values:[57,68,53,50,58,56,37,40,57,50,52,61], rationale:'Documentos presidenciais sustentam voluntarismo cívico, cooperação público-privada e reservas à assistência federal direta antes da expansão do New Deal.', caveats:'O recorte é o mandato e a crise de 1929–1933, não toda a carreira humanitária de Hoover. Valores próximos ao centro refletem posições insuficientemente comparáveis.', title:'Inaugural Address, 1929', url:'https://www.presidency.ucsb.edu/documents/presidential-documents-archive-guidebook/inaugural-addresses', note:'Arquivo universitário de discursos presidenciais reproduz a posse primária de Hoover.', evidence:{est:'medium',rep:'medium',eco:'medium',con:'medium',int:'medium',tec:'medium'} },
  { id:'harry-s-truman', name:'Harry S. Truman', category:'historical-figure', period:'Fair Deal e presidência, 1945–1953', values:[61,79,71,50,80,38,69,72,50,55,70,64], rationale:'A posse e o Fair Deal defendem seguridade, direitos civis e expansão de programas federais; o mandato também empregou poder militar na Guerra da Coreia.', caveats:'A política externa mistura contenção e ação militar, portanto o eixo de não intervenção permanece baixo; não se infere opinião pessoal de cada medida estatal.', title:'Inaugural Address, 1949', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-4', note:'Texto primário do programa de Truman, com liberdade, autogoverno e segurança coletiva; políticas internas constam dos documentos do Fair Deal.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'dwight-eisenhower', name:'Dwight D. Eisenhower', category:'historical-figure', period:'Presidências e política de Guerra Fria, 1953–1961', values:[58,79,72,50,72,40,58,63,57,53,58,72], rationale:'Discursos presidenciais sustentam contenção e defesa, investimento em infraestrutura e alerta contra a influência excessiva do complexo militar-industrial.', caveats:'O discurso de despedida é reflexão, não um resumo neutro de todas as políticas do governo. A nota temporaliza as declarações citadas.', title:'President Dwight D. Eisenhower’s Farewell Address (1961)', url:'https://www.archives.gov/milestone-documents/president-dwight-d-eisenhowers-farewell-address', note:'Transcrição oficial do National Archives do discurso de despedida de Eisenhower.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',tec:'medium'} },
  { id:'john-f-kennedy', name:'John F. Kennedy', category:'historical-figure', period:'Presidência e Nova Fronteira, 1961–1963', values:[60,84,69,50,73,35,65,68,50,50,68,79], rationale:'Discursos e legislação da Nova Fronteira documentam direitos civis, expansão de programas públicos, corrida espacial e engajamento internacional.', caveats:'A crise dos mísseis e a Guerra Fria moldam a política externa do recorte; a imagem pública não substitui a leitura de decisões concretas.', title:'Inaugural Address, 1961', url:'https://www.presidency.ucsb.edu/documents/presidential-documents-archive-guidebook/inaugural-addresses', note:'Arquivo de transcrições primárias lista a posse de Kennedy e discursos do seu mandato.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',mor:'medium',tec:'high'} },
  { id:'lyndon-b-johnson', name:'Lyndon B. Johnson', category:'historical-figure', period:'Great Society e Guerra do Vietnã, 1963–1969', values:[60,80,72,50,82,30,78,80,53,50,78,64], rationale:'A Great Society e a legislação de direitos civis expandiram programas públicos; a escalada no Vietnã documenta uma política externa militarmente intervencionista.', caveats:'Políticas domésticas e guerra apontam em direções distintas. Valores culturais sem evidência clara permanecem no centro.', title:'Annual Message to the Congress on the State of the Union, 1965', url:'https://www.presidency.ucsb.edu/documents/annual-message-the-congress-the-state-the-union-26', note:'Transcrição primária do discurso de 4 de janeiro de 1965 em que Johnson apresentou a Great Society.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'high',con:'high',mor:'medium'} },
  { id:'richard-nixon', name:'Richard Nixon', category:'historical-figure', period:'Presidência e détente, 1969–1974', values:[54,60,78,52,76,38,62,63,56,50,46,68], rationale:'A presidência combinou expansão de órgãos reguladores e programas ambientais com guerra no Sudeste Asiático, abertura à China e política de segurança nacional centralizada.', caveats:'O perfil se refere ao exercício da presidência e aos documentos publicados, incluindo o contexto de Watergate; não é um retrato de preferências privadas.', title:'Inaugural Address, 1969', url:'https://www.presidency.ucsb.edu/documents/presidential-documents-archive-guidebook/inaugural-addresses', note:'Transcrição do arquivo presidencial para a posse de Nixon; o corpus também indexa suas mensagens e discursos.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',tec:'medium'} },
  { id:'gerald-ford', name:'Gerald Ford', category:'historical-figure', period:'Presidência e recuperação pós-Watergate, 1974–1977', values:[58,79,62,50,62,48,48,43,52,50,52,60], rationale:'Pronunciamentos e atos de Ford enfatizam restauração da confiança constitucional e moderação econômica após Watergate e a crise inflacionária.', caveats:'O perdão de Nixon continua sendo decisão controversa; o vetor não pressupõe consenso sobre seu efeito institucional.', title:'Remarks Upon Taking the Oath of Office as President, 1974', url:'https://www.fordlibrarymuseum.gov/library/document/0248/whpr19740809-001.pdf', note:'Transcrição primária digitalizada pela Gerald R. Ford Presidential Library, caixa de comunicados da Casa Branca, 9 de agosto de 1974.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',eco:'medium',con:'medium'} },
  { id:'jimmy-carter', name:'Jimmy Carter', category:'historical-figure', period:'Presidência e direitos humanos, 1977–1981', values:[61,85,37,38,28,76,61,55,44,71,78,69], rationale:'A posse documenta compromisso com direitos humanos, diversidade e paz; a energia e a política social do mandato sustentam planejamento público moderado.', caveats:'A resposta à crise dos reféns e as tensões da Guerra Fria limitam qualquer leitura simples de não intervenção.', title:'Inaugural Address, 1977', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-0', note:'Texto primário de posse sobre direitos, pluralidade, desenvolvimento e paz internacional.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',int:'medium',eco:'medium',mor:'medium',tec:'medium'} },
  { id:'ronald-reagan', name:'Ronald Reagan', category:'historical-figure', period:'Presidências e programa conservador, 1981–1989', values:[48,74,75,64,81,32,28,22,39,40,32,78], rationale:'Discursos presidenciais defendem redução de impostos e do alcance federal, valores tradicionais, reconstrução militar e apoio a movimentos anticomunistas.', caveats:'Os programas e alianças do governo nem sempre seguiram a retórica de governo limitado. O período inclui negociação de controle de armas e intervenção externa.', title:'Second Inaugural Address, 1985', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-10', note:'Transcrição integral da posse de Reagan em 1985, documento primário para liberdade econômica, defesa e tecnologia.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'medium',con:'medium',mor:'medium',tec:'medium'} },
  { id:'george-h-w-bush', name:'George H. W. Bush', category:'historical-figure', period:'Presidência e fim da Guerra Fria, 1989–1993', values:[59,77,72,53,77,43,57,55,48,51,57,66], rationale:'A posse e os atos presidenciais descrevem transição internacional, ação militar no Golfo e compromissos internos moderados.', caveats:'Um discurso inaugural condensa compromissos, mas não representa toda a gestão nem resolve ambiguidades de política econômica e social.', title:'Inaugural Address, 1989', url:'https://www.presidency.ucsb.edu/documents/inaugural-address', note:'Transcrição primária da posse de Bush, com referências a democracia, responsabilidade pública e política internacional.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',tec:'medium'} },
  { id:'bill-clinton', name:'Bill Clinton', category:'historical-figure', period:'Presidências e Novo Democrata, 1993–2001', values:[63,84,63,47,64,44,55,49,36,65,72,73], rationale:'As posses e atos presidenciais associam o governo a comércio aberto, reformas de assistência social, direitos civis e internacionalismo pós-Guerra Fria.', caveats:'A entrada descreve um período e inclui decisões controversas, como política criminal e intervenções; valores não citados diretamente ficam no centro.', title:'Second Inaugural Address, 1997', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-1', note:'Transcrição do discurso presidencial primário; as mensagens e atos do mandato complementam o período.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',com:'medium',mor:'medium',tec:'medium'} },
  { id:'george-w-bush', name:'George W. Bush', category:'historical-figure', period:'Presidência e Guerra ao Terror, 2001–2009', values:[52,70,79,54,85,24,52,44,57,50,42,74], rationale:'A posse e a Doutrina Bush documentam expansão de segurança e intervenção preventiva, acompanhadas de cortes de impostos e investimento em tecnologia de defesa.', caveats:'O recorte é moldado pelos atentados de 11 de setembro e guerras subsequentes; não generaliza para a política externa americana fora daquele período.', title:'Second Inaugural Address, 2005', url:'https://www.presidency.ucsb.edu/documents/inaugural-address-13', note:'Transcrição primária da posse de Bush, dedicada em grande parte a democracia e estratégia internacional.', evidence:{est:'medium',rep:'medium',pod:'high',dip:'high',int:'medium',eco:'medium',con:'medium',tec:'medium'} },
  { id:'kamala-harris', name:'Kamala Harris', category:'public-figure', period:'Agenda presidencial e propostas públicas, 2021–2026', values:[64,86,56,38,46,46,64,60,39,65,77,77], rationale:'O recorte usa propostas e documentos assinados pela própria candidata e vice-presidente sobre direitos, trabalho, clima e inovação.', caveats:'A atuação como vice-presidente não oferece autoria individual de toda decisão da administração; os documentos citados devem corresponder ao período e à autoria indicados.', title:'Propostas de campanha e pronunciamentos públicos', url:'https://kamalaharris.com/issues/', note:'Arquivo de propostas da campanha presidencial de Harris; usar somente compromissos nela publicados sob sua própria candidatura.', evidence:{rep:'medium',eco:'medium',con:'medium',mor:'medium',tec:'medium'} },
  { id:'hillary-clinton', name:'Hillary Clinton', category:'public-figure', period:'Plataforma presidencial e serviço público, 2016–2024', values:[68,88,66,42,59,42,62,58,44,75,84,74], rationale:'A plataforma de 2016 e os pronunciamentos próprios defendem participação eleitoral, direitos civis, seguro de saúde e engajamento internacional.', caveats:'O vetor representa a candidatura e o registro público delimitado, não uma opinião medida nem todas as posições adotadas em cargos anteriores.', title:'2016 Democratic Party Platform, seção de propostas da candidata', url:'https://www.presidency.ucsb.edu/documents/2016-democratic-party-platform', note:'Texto integral da plataforma da candidatura presidencial de Clinton; é programa eleitoral explicitamente endossado pela candidata.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',int:'medium',eco:'medium',mor:'medium',tec:'medium'} },
  { id:'john-mccain', name:'John McCain', category:'historical-figure', period:'Atuação senatorial e campanhas presidenciais, 1987–2018', values:[58,80,66,46,74,39,51,49,48,53,58,71], rationale:'Discursos e votos de McCain defendem reforma eleitoral, defesa robusta, imigração legal e ciência; suas posições não se reduzem a um partido.', caveats:'A longa carreira teve mudanças e dissensos públicos, inclusive na política externa e fiscal; o perfil usa intervenções e votos identificáveis.', title:'Remarks on Campaign Finance Reform, October 3, 1996 (Congressional Record)', url:'https://www.govinfo.gov/content/pkg/CREC-1996-10-03/pdf/CREC-1996-10-03-pt1-PgS12287.pdf', note:'Registro oficial do Congressional Record com a fala de McCain no Senado sobre reforma do financiamento eleitoral.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',mor:'medium',tec:'medium'} },
  { id:'nancy-pelosi', name:'Nancy Pelosi', category:'public-figure', period:'Liderança na Câmara e agenda legislativa, 2007–2026', values:[64,86,61,42,55,43,74,69,39,66,76,77], rationale:'Projetos e discursos de sua liderança documentam a ampliação de programas públicos, direitos civis, investimento climático e inovação.', caveats:'Votos de uma liderança refletem coalizões e negociação legislativa, não necessariamente preferências pessoais em todos os eixos.', title:'Congressional Record and House legislative record', url:'https://www.congress.gov/member/nancy-pelosi/P000197', note:'Registro oficial do Congresso dos EUA com projetos, coautorias e atuação legislativa de Pelosi.', evidence:{est:'medium',rep:'medium',eco:'medium',con:'medium',mor:'medium',tec:'medium'} },
  { id:'mitch-mcconnell', name:'Mitch McConnell', category:'public-figure', period:'Liderança no Senado e declarações legislativas, 2007–2026', values:[51,72,72,50,69,38,32,30,51,50,37,62], rationale:'Discursos e registros do Senado documentam sua atuação por cortes tributários, desregulação e uma agenda judicial conservadora, além de políticas de segurança.', caveats:'O perfil é da liderança política em períodos delimitados; negociação partidária e votos de bloco não equivalem a declaração pessoal em todos os temas.', title:'Congressional Record and official Senate record', url:'https://www.congress.gov/member/mitch-mcconnell/M000355', note:'Registro oficial de proposições, votos e atuação parlamentar de McConnell.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'robert-f-kennedy', name:'Robert F. Kennedy', category:'historical-figure', period:'Atuação como procurador-geral e campanha presidencial, 1961–1968', values:[61,85,59,43,44,61,62,62,50,56,84,52], rationale:'Pronunciamentos e campanha documentam direitos civis, redução da pobreza, reforma da política externa e ceticismo diante da guerra do Vietnã.', caveats:'As posições evoluíram durante a campanha de 1968. A entrada se limita a pronunciamentos e propostas daquele período.', title:'Remarks on the assassination of Martin Luther King Jr., 1968', url:'https://www.jfklibrary.org/learn/about-jfk/the-kennedy-family/robert-f-kennedy/robert-f-kennedy-speech-at-the-city-club-of-cleveland', note:'Transcrição arquivada de pronunciamentos públicos de Kennedy durante a campanha de 1968.', evidence:{est:'medium',rep:'medium',dip:'medium',int:'medium',eco:'medium',mor:'high'} },
  { id:'thurgood-marshall', name:'Thurgood Marshall', category:'historical-figure', period:'Litígios de direitos civis e Suprema Corte, 1936–1991', values:[69,94,41,26,28,62,55,52,47,67,95,50], rationale:'As peças e votos de Marshall defendem igualdade perante a lei, integração, devido processo e limites a discriminação institucional.', caveats:'A codificação centra-se em trabalho jurídico e votos judiciais; sua defesa de direitos não fornece posições seguras para muitos eixos econômicos ou tecnológicos.', title:'Brief for the Petitioners, Brown v. Board of Education', url:'https://www.archives.gov/milestone-documents/brown-v-board-of-education', note:'Arquivo oficial do caso histórico; reúne documentos e contexto do litígio que Marshall apresentou pela NAACP.', evidence:{rep:'high',imi:'medium',dip:'medium',int:'medium',rel:'medium',mor:'high'} },
  { id:'shirley-chisholm', name:'Shirley Chisholm', category:'historical-figure', period:'Atuação no Congresso e candidatura presidencial, 1969–1982', values:[71,94,39,30,24,68,75,68,47,68,95,57], rationale:'Discursos, projetos e a campanha presidencial defendem representação democrática, educação e assistência pública, direitos das mulheres e redução do militarismo.', caveats:'A candidatura de 1972 e a atuação parlamentar são recortes ligados; temas sem propostas documentadas permanecem desconhecidos.', title:'Unbought and Unbossed campaign archive', url:'https://www.loc.gov/item/afc1986022.afc1986022_ms2201/', note:'Coleção primária de documentos e materiais da campanha de Chisholm, preservada pela Library of Congress.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'high'} },
  { id:'barry-goldwater', name:'Barry Goldwater', category:'historical-figure', period:'The Conscience of a Conservative e campanha de 1964', values:[31,72,64,55,70,33,18,10,44,48,36,65], rationale:'O livro e a plataforma de campanha defendem governo federal restrito, livre iniciativa e anticomunismo, com oposição a certas leis federais de direitos civis.', caveats:'A defesa de direitos civis e as posições federais de Goldwater mudaram conforme a questão; o vetor preserva a tensão em vez de tratá-lo como anti-institucional em todos os temas.', title:'The Conscience of a Conservative, 1960', url:'https://archive.org/details/conscienceofcons00gold', note:'Livro político autoral de Goldwater usado como fonte primária para suas posições sobre governo, mercado e federalismo.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'high',con:'high',mor:'medium'} },
  { id:'henry-a-wallace', name:'Henry A. Wallace', category:'historical-figure', period:'New Deal e campanha presidencial progressista, 1933–1948', values:[68,85,46,36,25,74,80,80,64,57,87,72], rationale:'Discursos e plataforma progressista defendem segurança econômica, direitos civis, cooperação internacional e uso pacífico de tecnologia.', caveats:'Wallace ocupou cargos em administrações distintas e depois dirigiu uma candidatura própria; o vetor usa textos do período progressista, não todo o mandato no gabinete.', title:'Progressive Party Platform of 1948 (archive index)', url:'https://www.presidency.ucsb.edu/people/other/minorthird-party-platforms', note:'Índice do American Presidency Project que disponibiliza a plataforma eleitoral primária de 1948 do partido de Wallace.', evidence:{est:'medium',rep:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',com:'medium',mor:'medium',tec:'medium'} },
  { id:'eugene-v-debs', name:'Eugene V. Debs', category:'historical-figure', period:'Discursos socialistas e movimento trabalhista, 1894–1920', values:[74,89,29,35,17,82,88,87,61,57,88,50], rationale:'Discursos de Debs defendem sindicalismo, propriedade social, sufrágio e oposição à guerra mundial.', caveats:'O texto de 1918 foi pronunciado durante repressão de guerra e levou a sua condenação; eixos não discutidos ficam no centro.', title:'Statement to the Court, 1918', url:'https://www.marxists.org/archive/debs/works/1918/court.htm', note:'Transcrição do pronunciamento primário de Debs após sua condenação sob a Lei de Espionagem.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'high',eco:'high',con:'high',mor:'medium'} },
  { id:'huey-long', name:'Huey P. Long', category:'historical-figure', period:'Governos da Louisiana e Share Our Wealth, 1928–1935', values:[42,49,72,52,65,50,90,81,62,49,62,53], rationale:'O programa Share Our Wealth propunha redistribuição federal, limites à riqueza e serviços públicos; a governança estadual concentrava poder executivo.', caveats:'A proposta econômica documentada coexistiu com práticas clientelistas e ataques à oposição. Não confundimos populismo econômico com pluralismo democrático.', title:'Share Our Wealth radio addresses', url:'https://www.senate.gov/artandhistory/history/minute/Every_Man_A_King.htm', note:'Arquivo histórico do Senado sobre o programa e os discursos públicos de Long; a proposta distribuía renda por ação federal.', evidence:{est:'medium',rep:'medium',pod:'medium',eco:'high',con:'high',com:'medium',mor:'medium'} },
  { id:'robert-la-follette', name:'Robert M. La Follette', category:'historical-figure', period:'Progressivismo e oposição à Primeira Guerra, 1900–1925', values:[73,86,47,50,19,83,67,71,61,51,79,50], rationale:'A atuação progressista e seu discurso contra a guerra defendem reforma democrática, regulação e liberdade de crítica em tempo de conflito.', caveats:'A fonte de 1917 documenta uma intervenção clara, mas não cobre todos os assuntos modernos; por isso, vários eixos ficam no centro.', title:'Free Speech in Wartime, 1917', url:'https://www.senate.gov/artandhistory/history/common/generic/Speeches_LaFollette_FreeSpeech.htm', note:'Discurso de La Follette reproduzido pelo Senado dos EUA e contextualizado pelo Senado como defesa da fala pública contra guerra.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'high',eco:'medium',con:'medium',mor:'medium'} },
  { id:'william-jennings-bryan', name:'William Jennings Bryan', category:'historical-figure', period:'Plataformas presidenciais e campanha anti-imperialista, 1896–1908', values:[72,82,45,52,27,73,62,69,66,44,69,40], rationale:'As plataformas democratas sob liderança de Bryan defendem prata livre, proteção ao trabalho, limitação do poder corporativo e oposição ao imperialismo.', caveats:'A fonte é programa de partido em campanhas lideradas por Bryan, e não prova de que cada posição fosse pessoal ou permanecesse constante.', title:'1896 Democratic Party platform', url:'https://www.presidency.ucsb.edu/documents/1896-democratic-party-platform', note:'Plataforma eleitoral original de 1896, em campanha presidencial de Bryan; apoio é limitado aos compromissos explicitados no texto.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',com:'medium',rel:'medium'} },
  { id:'john-c-calhoun', name:'John C. Calhoun', category:'historical-figure', period:'Discursos sobre escravidão e soberania estadual, 1830–1850', values:[9,21,58,83,54,47,33,41,51,39,4,50], rationale:'Seus discursos defendem nulificação, soberania estadual e escravidão; a posição se opõe à igualdade democrática e aos direitos universais.', caveats:'O perfil documenta uma defesa explícita da escravidão e hierarquia racial, não recomenda nem normaliza suas posições. Seu regionalismo não corresponde ao federalismo democrático moderno.', title:'Speech on the reception of abolition petitions, 1837', url:'https://www.senate.gov/artandhistory/history/resources/pdf/Calhoun_Petitions.pdf', note:'Registro primário de discurso de Calhoun no Senado contra petições abolicionistas; a fonte deve ser lida no contexto escravista do período.', evidence:{est:'high',rep:'high',imi:'high',eco:'medium',rel:'medium',mor:'high'} },
  { id:'susan-b-anthony', name:'Susan B. Anthony', category:'historical-figure', period:'Sufrágio feminino e cidadania, 1851–1906', values:[68,96,34,30,20,71,53,49,47,62,99,50], rationale:'Textos e discursos de Anthony defendem voto igual, autonomia civil das mulheres e aplicação universal da cidadania republicana.', caveats:'Sua campanha pelo sufrágio contém episódios de exclusão racial e desacordo estratégico com outras ativistas; o vetor retrata demandas expressas, não toda a trajetória.', title:'History of Woman Suffrage, volume I', url:'https://www.gutenberg.org/files/15220/15220-h/15220-h.htm', note:'História documental da campanha escrita por Anthony, Stanton e Gage, com discursos, cartas e registros primários.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',rel:'medium',mor:'high'} },
  { id:'sojourner-truth', name:'Sojourner Truth', category:'historical-figure', period:'Abolicionismo e direitos das mulheres, 1843–1883', values:[65,91,40,21,19,65,57,52,45,63,96,50], rationale:'Discursos públicos e o relato autobiográfico defendem abolição, cidadania negra e direitos das mulheres.', caveats:'A famosa transcrição “Ain’t I a Woman?” foi registrada por terceiros e teve versões editadas; evitamos tratá-la como transcrição literal única.', title:'The Narrative of Sojourner Truth', url:'https://docsouth.unc.edu/neh/truth/truth.html', note:'Edição digital da University of North Carolina de sua narrativa autobiográfica, publicada com autorização em vida.', evidence:{est:'medium',rep:'medium',imi:'medium',dip:'medium',mor:'high',rel:'medium'} },
  { id:'william-lloyd-garrison', name:'William Lloyd Garrison', category:'historical-figure', period:'Abolicionismo e não resistência, 1831–1865', values:[64,83,32,23,14,87,52,55,48,57,96,50], rationale:'Editorials e escritos de Garrison defendem abolição imediata, igualdade civil, não resistência e crítica à guerra.', caveats:'A defesa de dissolução da União e a oposição não resistente à guerra situam o texto em circunstâncias próprias do século XIX.', title:'The Liberator, inaugural issue, 1831', url:'https://www.masshist.org/database/1667', note:'Arquivo digital da Massachusetts Historical Society com a publicação abolicionista original fundada por Garrison.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'high',mor:'high'} },
  { id:'web-du-bois', name:'W. E. B. Du Bois', category:'historical-figure', period:'The Souls of Black Folk e atuação pan-africana, 1903–1963', values:[71,91,45,24,27,67,70,68,53,55,97,50], rationale:'Ensaios e campanhas de Du Bois defendem direitos civis, sufrágio, integração e igualdade econômica e racial.', caveats:'Sua trajetória política mudou e incluiu aproximações tardias com o comunismo; o perfil usa o período e obras citados, não apaga essa evolução.', title:'The Souls of Black Folk, 1903', url:'https://www.gutenberg.org/ebooks/408', note:'Texto autoral de Du Bois sobre raça, cidadania e democracia; outras posições derivam de campanhas e obras datadas.', evidence:{est:'medium',rep:'high',imi:'medium',eco:'medium',rel:'medium',mor:'high'} },
  { id:'booker-t-washington', name:'Booker T. Washington', category:'historical-figure', period:'Atuação educacional e Atlanta Exposition Address, 1895–1915', values:[60,66,49,43,24,61,56,68,50,58,72,56], rationale:'Discursos de Washington defendem educação vocacional, propriedade e avanço econômico gradual para comunidades negras.', caveats:'O discurso de Atlanta enfatizou acomodação política e foi contestado por outros ativistas. O centro em dimensões sem fonte explícita é desconhecimento.', title:'Up from Slavery, 1901', url:'https://www.gutenberg.org/ebooks/2376', note:'Autobiografia autorizada de Washington, fonte primária de suas posições públicas e estratégia educacional.', evidence:{est:'medium',rep:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'ida-b-wells', name:'Ida B. Wells', category:'historical-figure', period:'Jornalismo anti-linchamento e sufrágio, 1892–1931', values:[69,93,42,23,19,67,60,52,49,61,97,50], rationale:'Investigação e panfletos de Wells denunciam linchamentos, segregação e violência política; sua atuação também documenta organização pelo sufrágio.', caveats:'Os textos foram escritos em contexto de violência racial e têm como alvo a defesa pública de pessoas ameaçadas; o vetor não infere posições econômicas além das fontes.', title:'Southern Horrors: Lynch Law in All Its Phases, 1892', url:'https://www.loc.gov/item/13021603/', note:'Panfleto primário de Wells preservado e digitalizado pela Library of Congress.', evidence:{est:'medium',rep:'high',pod:'medium',imi:'medium',int:'medium',mor:'high'} },
  { id:'james-baldwin', name:'James Baldwin', category:'historical-figure', period:'Ensaios sobre direitos civis e democracia, 1955–1987', values:[66,90,38,21,20,73,67,59,45,69,96,50], rationale:'Ensaios e discursos de Baldwin criticam racismo, exclusão social e militarismo e defendem liberdade, justiça e pluralismo.', caveats:'Baldwin era escritor e crítico público, não ocupante de cargo eletivo; suas posições devem ser lidas por meio das obras citadas.', title:'The Fire Next Time, 1963', url:'https://archive.org/details/firenexttime00bald', note:'Edição digital de obra autoral de Baldwin sobre raça, religião e cidadania nos Estados Unidos.', evidence:{est:'medium',rep:'medium',imi:'medium',dip:'medium',int:'medium',rel:'medium',mor:'high'} },
  { id:'harvey-milk', name:'Harvey Milk', category:'historical-figure', period:'Mandato municipal e ativismo LGBTQ+, 1973–1978', values:[67,95,44,25,18,65,59,57,52,81,99,50], rationale:'Discursos e atuação eleitoral de Milk defendem igualdade civil, participação local e direitos de pessoas LGBTQ+.', caveats:'A passagem por um cargo municipal foi breve e os registros focam direitos e representação; não se inferem posições econômicas sem fonte.', title:'The Hope Speech, 1978', url:'https://www.loc.gov/item/ihas.200197402/', note:'Gravação e transcrição arquivadas pela Library of Congress de discurso eleitoral de Milk.', evidence:{est:'medium',rep:'high',pod:'medium',imi:'medium',rel:'high',mor:'high'} },
  { id:'cesar-chavez', name:'César Chávez', category:'historical-figure', period:'Organização trabalhista e direitos dos trabalhadores rurais, 1962–1993', values:[72,89,33,35,13,77,77,70,52,51,89,50], rationale:'Discursos e campanhas da United Farm Workers defendem organização sindical, direitos laborais, boicote não violento e ação coletiva.', caveats:'O perfil usa textos do movimento que Chávez liderou e não pretende resumir as posições de todos os trabalhadores rurais.', title:'Commonwealth Club Address, 1984', url:'https://ufw.org/research/history/story-cesar-chavez/', note:'Arquivo da UFW com documentos e transcrições originais de Chávez e da organização sindical que fundou.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'high',eco:'medium',con:'medium',mor:'medium'} },
  { id:'dolores-huerta', name:'Dolores Huerta', category:'public-figure', period:'Organização trabalhista e defesa de direitos, 1960–2026', values:[73,91,33,29,14,75,78,72,48,57,96,50], rationale:'Discursos e trabalho organizativo da UFW defendem direitos laborais, participação política, igualdade de gênero e não violência.', caveats:'A codificação se baseia em declarações e campanhas públicas documentadas, não em afiliação partidária nem em posições presumidas.', title:'Dolores Huerta Foundation FAQ: biography and farmworker organizing', url:'https://doloreshuerta.org/faq/', note:'A própria fundação documenta a cofundação da UFW, o boicote e a atuação legislativa em direitos coletivos dos trabalhadores rurais.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'medium',mor:'high'} },
  { id:'ralph-nader', name:'Ralph Nader', category:'public-figure', period:'Defesa do consumidor e plataformas presidenciais, 1965–2026', values:[76,91,36,35,22,77,65,60,50,59,84,50], rationale:'Livros, campanhas e iniciativas de Nader documentam regulação de segurança do consumidor, responsabilização corporativa e crítica a guerras.', caveats:'É uma longa atuação pública fora de cargos executivos; fontes específicas sustentam apenas os eixos indicados.', title:'Unsafe at Any Speed, 1965 (author bibliography)', url:'https://nader.org/2005/01/02/books/', note:'Bibliografia no site de Nader identifica seu livro autoral de 1965; os demais eixos citados dependem das outras fontes listadas no perfil.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'gary-johnson', name:'Gary Johnson', category:'public-figure', period:'Governos do Novo México e campanhas presidenciais, 1995–2016', values:[25,80,32,45,25,82,18,16,22,80,68,70], rationale:'A plataforma presidencial libertária e seus pronunciamentos próprios defendem limites ao governo, livre comércio, legalização de drogas e não intervenção.', caveats:'Sua passagem de governador republicano a candidato libertário exige separar cada período; este vetor privilegia o programa de 2016, não uma essência ideológica.', title:'Libertarian Party Platform, adopted 2016', url:'https://lpedia.org/wiki/Document:National_Platform_2016', note:'Transcrição arquivada da plataforma adotada em convenção em maio de 2016; o texto de partido é atribuído a Johnson apenas no recorte de sua candidatura.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',int:'high',eco:'high',con:'high',com:'high',rel:'medium',mor:'medium',tec:'medium'} },

  // Canada — the period and document determine the profile; living figures use their own published platforms.
  { id:'john-a-macdonald', name:'John A. Macdonald', category:'historical-figure', period:'Governo da Confederação e política nacional, 1867–1891', values:[39,56,63,71,68,39,67,72,82,54,40,45], rationale:'Discursos e a política nacional documentam construção federal, tarifas protecionistas, expansão ferroviária e assimilação estatal de povos indígenas.', caveats:'A política de Macdonald promoveu a colonização e o sistema de escolas residenciais; o perfil registra poder estatal e coerção, não uma celebração do fundador.', title:'Confederation debates and National Policy speeches', url:'https://www.ourcommons.ca/Parliamentarians/en/prime-ministers', note:'Arquivo parlamentar para discursos e registros de Macdonald; os documentos da Confederação e da Política Nacional delimitam este recorte.', evidence:{est:'medium',rep:'medium',pod:'medium',imi:'high',dip:'medium',eco:'medium',con:'medium',com:'high',mor:'medium'} },
  { id:'wilfrid-laurier', name:'Wilfrid Laurier', category:'historical-figure', period:'Governo liberal e expansão econômica, 1896–1911', values:[64,76,49,54,44,62,46,55,46,50,57,47], rationale:'Discursos e registros do governo combinam federalismo canadense, imigração e expansão econômica com recusa à conscrição na Primeira Guerra.', caveats:'Sua oposição à conscrição não equivale a pacifismo absoluto: Laurier apoiou o envio voluntário de tropas. O perfil se restringe a políticas documentadas do período.', title:'The Political Life of Sir Wilfrid Laurier', url:'https://parks.canada.ca/lhn-nhs/on/laurier/culture/natcul7', note:'Parks Canada reproduz o contexto político e links de arquivo; o período e os episódios citados são rastreáveis aos registros de Laurier.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',com:'medium'} },
  { id:'mackenzie-king', name:'William Lyon Mackenzie King', category:'historical-figure', period:'Governos liberais e Segunda Guerra, 1921–1948', values:[66,73,67,55,62,48,65,66,52,50,55,56], rationale:'Diários, discursos e decisões do governo documentam federalismo fiscal, expansão gradual da seguridade social e mobilização durante a guerra.', caveats:'King foi pragmático e suas políticas variaram por conjuntura; os valores centrais indicam evidência insuficiente em temas não documentados.', title:'The Diaries of William Lyon Mackenzie King', url:'https://www.canada.ca/en/library-archives/collection/research-help/politics-government-law/diaries-william-lyon-mackenzie-king.html', note:'Biblioteca e Arquivos do Canadá disponibiliza o diário primário de King, que cobre sua vida política e os anos como primeiro-ministro.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium'} },
  { id:'robert-borden', name:'Robert Borden', category:'historical-figure', period:'Governo e conscrição durante a Primeira Guerra, 1911–1920', values:[62,67,75,55,81,35,58,66,69,51,48,50], rationale:'Discursos e leis do governo documentam conscrição, mobilização industrial e ampliação do poder federal em tempo de guerra.', caveats:'A coalizão de união e as divisões sobre conscrição pertencem ao contexto excepcional de guerra; não generalizamos o período para todas as posições pessoais.', title:'War measures and parliamentary debates', url:'https://www.ourcommons.ca/Parliamentarians/en/prime-ministers', note:'Índice oficial de primeiros-ministros e registros parlamentares; a codificação usa discursos e legislação do mandato de guerra de Borden.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'medium',com:'medium'} },
  { id:'lester-b-pearson', name:'Lester B. Pearson', category:'historical-figure', period:'Governo minoritário e expansão social, 1963–1968', values:[69,88,44,45,28,76,74,72,42,57,79,65], rationale:'Discursos e legislação do governo documentam Medicare, pensões, política externa multilateral e manutenção da paz.', caveats:'A posição sobre a Guerra do Vietnã e defesa internacional variou entre crítica e aliança; a leitura de intervenção é por isso moderada.', title:'Official speeches and parliamentary records', url:'https://www.ourcommons.ca/Parliamentarians/en/prime-ministers', note:'Registros parlamentares e discursos de Pearson sustentam as políticas do período de governo de 1963–1968.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'high',eco:'medium',con:'medium',mor:'medium'} },
  { id:'john-diefenbaker', name:'John Diefenbaker', category:'historical-figure', period:'Governo conservador e Canadian Bill of Rights, 1957–1963', values:[62,83,57,47,56,50,50,52,54,55,72,57], rationale:'A Carta Canadense de Direitos e a Bill of Rights defendem liberdades civis, igualdade legal e direitos políticos em âmbito federal.', caveats:'As leis de direitos coexistiram com controvérsias sobre política indígena e alianças militares; os eixos sem apoio documental ficam desconhecidos.', title:'Canadian Bill of Rights, 1960', url:'https://laws-lois.justice.gc.ca/eng/acts/c-12.3/', note:'Texto oficial primário da lei aprovada sob o governo de Diefenbaker.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'medium',int:'medium',rel:'medium',mor:'medium'} },
  { id:'pierre-trudeau', name:'Pierre Elliott Trudeau', category:'historical-figure', period:'Primeiro-ministro e patriation da Constituição, 1968–1984', values:[58,88,59,34,45,62,64,61,46,75,83,62], rationale:'A Constituição de 1982, a Carta de Direitos e a política oficial de multiculturalismo documentam direitos individuais, federalismo e pluralismo.', caveats:'A crise de Outubro e o uso da Lei de Medidas de Guerra são contraevidências importantes; a entrada não transforma uma única lei na avaliação completa do período.', title:'Constitution Act, 1982', url:'https://laws-lois.justice.gc.ca/eng/const/page-12.html', note:'Texto constitucional promulgado durante seu governo, fonte primária para direitos, federalismo e relações entre províncias e federação.', evidence:{est:'medium',rep:'high',pod:'medium',imi:'medium',int:'medium',rel:'medium',mor:'medium'} },
  { id:'tommy-douglas', name:'Tommy Douglas', category:'historical-figure', period:'Governo de Saskatchewan e Medicare, 1944–1961', values:[76,87,37,41,19,75,86,80,54,50,75,48], rationale:'O programa do CCF e as reformas provinciais de Douglas defendem propriedade pública, planejamento social, saúde universal e oposição à guerra.', caveats:'O programa partidário é uma fonte institucional do movimento que liderava, não uma transcrição das preferências pessoais de Douglas em todos os eixos.', title:'The Regina Manifesto, 1933', url:'https://www.douglascoldwelllayton.ca/the_regina_manifesto', note:'Transcrição do programa partidário adotado pelo CCF em 1933, preservada pela fundação histórica Douglas–Coldwell–Layton; sua relação com Douglas é institucional, não exclusivamente individual.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'high',con:'high',mor:'medium'} },
  { id:'jack-layton', name:'Jack Layton', category:'historical-figure', period:'Liderança federal do NDP, 2003–2011', values:[71,89,35,34,18,75,79,71,48,54,89,58], rationale:'Debates parlamentares registrados em 2011 mostram Layton defendendo saúde pública, proteção de renda e negociação de medidas para famílias e desempregados.', caveats:'A entrada usa intervenções do líder da oposição, sem inferir posições de afiliação partidária. Dimensões não documentadas nos trechos permanecem desconhecidas.', title:'House of Commons Debates (Hansard), March 24, 2011', url:'https://www.ourcommons.ca/DocumentViewer/en/40-3/house/sitting-148/hansard', note:'Registro parlamentar oficial de intervenções de Layton sobre orçamento e políticas públicas; sustenta somente dimensões explicitamente documentadas.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium'} },
  { id:'justin-trudeau', name:'Justin Trudeau', category:'public-figure', period:'Governos liberais e plataformas federais, 2015–2025', values:[65,87,49,35,37,65,63,61,43,71,81,79], rationale:'Plataformas e atos do governo defendem imigração, reconciliação indígena, direitos civis, precificação de carbono e inovação tecnológica.', caveats:'As promessas e resultados de governo são categorias distintas; a fonte indicada é a plataforma de 2025, e posições de campanhas anteriores não são automaticamente tratadas como iguais.', title:'Liberal Party of Canada 2025 platform, “Canada Strong”', url:'https://liberal.ca/wp-content/uploads/sites/292/2025/04/Canada-Strong.pdf', note:'PDF da plataforma oficial publicada pela campanha liberal de Mark Carney. O documento inclui compromissos do governo Trudeau anterior e nomeia propostas de liderança para 2025.', evidence:{est:'medium',rep:'medium',pod:'medium',int:'medium',eco:'medium',con:'medium',mor:'medium',tec:'medium'} },
  { id:'stephen-harper', name:'Stephen Harper', category:'historical-figure', period:'Governos conservadores e política fiscal, 2006–2015', values:[53,74,65,56,62,43,38,31,64,47,42,68], rationale:'Orçamento federal de 2015, apresentado pelo governo Harper, privilegia equilíbrio fiscal, baixa carga tributária e segurança. Não usamos afiliação partidária para preencher eixos sem evidência individual.', caveats:'O documento é de política governamental, não representa sozinho convicções de Harper nem sustenta todos os eixos do vetor.', title:'Economic Action Plan 2015 (Government of Canada budget)', url:'https://budget.canada.ca/2015/docs/nrc/2015-04-21-eng.html', note:'Fonte primária do governo da época sobre a agenda fiscal e de segurança; atribuição circunscrita ao período do governo Harper.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'medium',int:'medium',eco:'medium',com:'medium',mor:'medium'} },
  { id:'mark-carney', name:'Mark Carney', category:'public-figure', period:'Plataforma liberal e agenda governamental, 2025–2026', values:[66,85,52,38,43,65,63,62,41,68,76,86], rationale:'O mandato eleitoral e a agenda pública de Carney destacam democracia, economia de baixo carbono, comércio e investimento tecnológico.', caveats:'Este vetor aplica-se aos compromissos publicados para a eleição e ao período de governo observado; não presume opiniões em eixos que o programa não cobre.', title:'Canada Strong — Liberal Party of Canada 2025 platform', url:'https://liberal.ca/wp-content/uploads/sites/292/2025/04/Canada-Strong.pdf', note:'Plataforma eleitoral nacional publicada pela campanha de Carney em 2025; o vetor se limita a esse programa.', evidence:{est:'medium',rep:'medium',eco:'medium',con:'medium',com:'medium',mor:'medium',tec:'medium'} },
  { id:'pierre-poilievre', name:'Pierre Poilievre', category:'public-figure', period:'“Plan for Change” e programas públicos, 2025–2026', values:[43,78,61,57,53,43,33,28,62,51,41,74], rationale:'O plano e os pronunciamentos da própria candidatura defendem corte de impostos, desregulação, exploração de recursos e segurança pública.', caveats:'Os itens são propostas eleitorais ainda não implementadas no período da fonte; o vetor não trata suas promessas como resultados de governo.', title:'Poilievre Unveils His Plan for Change, 2025', url:'https://www.conservative.ca/poilievre-unveils-his-plan-for-change/', note:'Anúncio oficial da candidatura conservadora de Poilievre, que resume o programa e encaminha para a plataforma custeada.', evidence:{est:'medium',rep:'medium',pod:'medium',eco:'medium',con:'medium',com:'medium',tec:'medium'} },
  { id:'elizabeth-may', name:'Elizabeth May', category:'public-figure', period:'Liderança e plataformas do Green Party of Canada, 2006–2026', values:[77,92,31,23,15,77,62,72,40,63,91,47], rationale:'Manifestos e discursos de May e do partido que lidera defendem democracia participativa, ação climática, direitos e desmilitarização.', caveats:'Plataformas partidárias são coletivas; itens são incluídos quando May os apresentou publicamente ou os defendeu como líder.', title:'Green Party of Canada 2025 election platform', url:'https://www.greenparty.ca/wp-content/uploads/2025/04/GP_Platform_English_Final-1.pdf', note:'Programa eleitoral oficial apresentado pelo partido liderado por May; sustenta somente compromissos publicados nesse ciclo.', evidence:{est:'medium',rep:'medium',pod:'medium',dip:'high',int:'medium',eco:'medium',con:'medium',mor:'medium',tec:'medium'} },
  { id:'agnes-macphail', name:'Agnes Macphail', category:'historical-figure', period:'Primeira mulher eleita à Câmara dos Comuns, 1921–1940', values:[71,94,26,50,12,89,72,68,45,57,91,50], rationale:'Discursos parlamentares de Macphail defendem sufrágio, reformas penitenciárias e desmilitarização, inclusive sua oposição ao treinamento militar obrigatório.', caveats:'A amostra é de discursos parlamentares documentados; os eixos não diretamente tratados ficam desconhecidos.', title:'House of Commons Debates and parliamentary papers', url:'https://www.ourcommons.ca/Parliamentarians/en/members/Agnes-Macphail(6816)', note:'Registro institucional e debates parlamentares de Macphail, fonte primária para seu trabalho legislativo.', evidence:{est:'medium',rep:'high',pod:'medium',dip:'high',int:'high',eco:'medium',mor:'medium'} },
  { id:'nellie-mcclung', name:'Nellie McClung', category:'historical-figure', period:'Sufrágio e reforma social no Canadá, 1908–1936', values:[62,91,43,50,25,68,58,53,51,59,95,50], rationale:'Ensaios e discursos de McClung apoiam sufrágio feminino, temperança e reforma social; seu papel na campanha dos “Famous Five” é documentado em textos e arquivos.', caveats:'Alguns escritos refletem eugenia e exclusões hoje rejeitadas; a seleção se restringe ao trabalho sufragista e registra essas limitações.', title:'In Times Like These, 1915', url:'https://digital.library.upenn.edu/women/mcclung/times/times.html', note:'Edição digital do texto político de autoria de McClung, publicado em 1915, sobre sufrágio e reforma social.', evidence:{est:'medium',rep:'high',pod:'medium',int:'medium',rel:'medium',mor:'high'} },
  { id:'louis-riel', name:'Louis Riel', category:'historical-figure', period:'Resistências métis e governo provisório, 1869–1885', values:[85,57,49,18,47,53,68,64,52,51,62,50], rationale:'Declarações e listas de direitos do governo provisório de Red River defendem autogoverno métis, direitos linguísticos e negociação constitucional.', caveats:'A trajetória inclui dois levantes e conflitos armados; períodos e comunidades são complexos. Não equiparamos sua resistência a um manifesto contemporâneo.', title:'List of Rights of the Métis provisional government, 1869', url:'https://www.thecanadianencyclopedia.ca/en/article/louis-riel', note:'A página remete aos registros primários do governo provisório; as reivindicações de direitos e autogoverno foram documentadas no período.', evidence:{est:'high',rep:'medium',pod:'medium',imi:'medium',dip:'medium',mor:'medium'} },
  { id:'george-etienne-cartier', name:'George-Étienne Cartier', category:'historical-figure', period:'Confederação e formação do Canadá, 1858–1873', values:[37,72,55,34,58,58,59,65,59,52,59,44], rationale:'Discursos da Confederação defendem um governo federal e proteção de instituições linguísticas e religiosas franco-canadenses.', caveats:'O conceito de federalismo de 1867 não corresponde perfeitamente à escala atual; o perfil usa sua atuação política registrada, não o resultado posterior como intenção individual.', title:'Confederation debates, House of Commons', url:'https://www.ourcommons.ca/Parliamentarians/en/historical-figures', note:'Arquivo do Parlamento com materiais históricos e referências a discursos de Cartier na Confederação.', evidence:{est:'high',rep:'medium',imi:'medium',rel:'medium',mor:'medium',eco:'medium'} },
  { id:'robert-baldwin', name:'Robert Baldwin', category:'historical-figure', period:'Reforma parlamentar e governo responsável, 1836–1851', values:[78,87,32,50,23,75,56,51,49,50,71,50], rationale:'A atuação de Baldwin e Lafontaine documenta a transição a governo responsável, reforma constitucional e oposição à repressão após as rebeliões.', caveats:'A interpretação do movimento de reforma é retrospectiva; o eixo cultural e econômico permanece sem evidência direta suficiente.', title:'The Baldwin–Lafontaine government and responsible government records', url:'https://www.ourcommons.ca/Parliamentarians/en/historical-figures', note:'Arquivo histórico oficial do Parlamento canadense; os registros de debates e governo delimitam o recorte de reforma parlamentar.', evidence:{est:'high',rep:'medium',pod:'medium',dip:'medium',int:'medium',mor:'medium'} },
];

export const peopleNorthAmericaExpansion: ReferenceEntry[] = rows.map((row) => ({
  id: `na-${row.id}`,
  kind: 'person',
  category: row.category,
  name: row.name,
  period: row.period,
  // A score without a medium/high source-backed axis key is unknown, so it stays centered.
  vec: Object.fromEntries(keys.map((key, index) => [key, row.evidence[key] ? row.values[index] : 50])) as Record<AxisKey, number>,
  rationale: row.rationale,
  caveats: row.caveats,
  sources: [source(row.title, row.url, row.note)],
  evidence: row.evidence,
  axisEvidence: Object.fromEntries(Object.entries(row.evidence).map(([axis, strength]) => {
    const key = axis as AxisKey;
    const value = row.values[keys.indexOf(key)];
    const pole = axisPoles[key][value >= 50 ? 0 : 1];
    const axisName = ({ est:'federalismo', rep:'democracia', pod:'segurança', imi:'assimilação cultural', dip:'militarismo', int:'não intervenção', eco:'propriedade pública', con:'planejamento', com:'protecionismo', rel:'secularismo', mor:'progressismo', tec:'otimismo tecnológico' } as Record<AxisKey, string>)[key];
    return [key, {
      sourceTitles: [row.title],
      rationale: `Leitura editorial do eixo ${axisName}: o recorte citado sustenta o polo ${pole}; a fonte ampara a direção, não a precisão decimal. ${row.rationale}`,
    }];
  })) as ReferenceEntry['axisEvidence'],
}));
